<script type="application/ld+json">{"@context":"https://schema.org","@graph":[{"@type":"ProfessionalService","@id":"https://pennsylvaniainsuranceappraiser.com/#business","name":"Pennsylvania Insurance Appraiser","url":"https://pennsylvaniainsuranceappraiser.com/","telephone":"+1 (844) 537-1427","email":"info@pennsylvaniainsuranceappraiser.com","logo":{"@type":"ImageObject","@id":"https://pennsylvaniainsuranceappraiser.com/#logo","url":"https://pennsylvaniainsuranceappraiser.com/favicon-512.png","contentUrl":"https://pennsylvaniainsuranceappraiser.com/favicon-512.png","width":512,"height":512,"caption":"Pennsylvania Insurance Appraiser"},"image":{"@id":"https://pennsylvaniainsuranceappraiser.com/#logo"},"address":{"@type":"PostalAddress","addressRegion":"PA","addressCountry":"US"},"contactPoint":[{"@type":"ContactPoint","telephone":"+1 (844) 537-1427","email":"info@pennsylvaniainsuranceappraiser.com","contactType":"customer service","areaServed":"US-PA","availableLanguage":"en"}],"slogan":"Independent appraisal for underpaid Pennsylvania property claims","description":"Independent insurance appraisal, estimate review and umpire services for disputed property claims across all 67 Pennsylvania counties.","areaServed":[{"@type":"State","name":"Pennsylvania"},{"@type":"City","name":"Philadelphia"},{"@type":"City","name":"Pittsburgh"},{"@type":"City","name":"Allentown"},{"@type":"City","name":"Erie"},{"@type":"City","name":"Reading"},{"@type":"City","name":"Scranton"},{"@type":"City","name":"Lancaster"},{"@type":"City","name":"Harrisburg"},{"@type":"City","name":"State College"},{"@type":"City","name":"Wilkes-Barre"},{"@type":"City","name":"York"},{"@type":"City","name":"Johnstown"}],"hasOfferCatalog":{"@type":"OfferCatalog","name":"Insurance appraisal services","itemListElement":[{"@type":"Offer","itemOffered":{"@type":"Service","name":"Appraisal Demand Representation","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/appraisal-demand-representation/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Homeowner Claim Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/home-insurance-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Commercial & HOA Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/commercial-hoa-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Roof & Hail Damage Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/roof-hail-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Wind & Tornado Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/windstorm-tornado-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Tropical Storm Remnant Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/tropical-storm-remnant-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Water Damage Claim Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/water-damage-claim-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Fire & Smoke Damage Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/fire-smoke-damage-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Ice Dam & Frozen Pipe Appraisal","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/ice-dam-frozen-pipe-appraisal/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Insurance Estimate Review","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/insurance-estimate-audit/"}},{"@type":"Offer","itemOffered":{"@type":"Service","name":"Umpire & Neutral Services","url":"https://pennsylvaniainsuranceappraiser.com/property-appraisal-services/umpire-neutral-services/"}}]},"knowsAbout":["Insurance appraisal","Appraisal clause","Property claim valuation","Ice dam claims","Hail and wind damage","Water damage claims"],"openingHoursSpecification":[{"@type":"OpeningHoursSpecification","dayOfWeek":["Monday","Tuesday","Wednesday","Thursday","Friday"],"opens":"08:00","closes":"18:00"}],"priceRange":"$$"},{"@type":"WebSite","@id":"https://pennsylvaniainsuranceappraiser.com/#website","url":"https://pennsylvaniainsuranceappraiser.com/","name":"Pennsylvania Insurance Appraiser","publisher":{"@id":"https://pennsylvaniainsuranceappraiser.com/#business"},"inLanguage":"en-US"},{"@type":"WebPage","@id":"https://pennsylvaniainsuranceappraiser.com/insurance-appraisal-faq/#webpage","url":"https://pennsylvaniainsuranceappraiser.com/insurance-appraisal-faq/","name":"Insurance Appraisal FAQ | Pennsylvania Claims","description":"Insurance appraisal FAQ for Pennsylvania: how it works, fees, the one-year suit clause, the Insurance Department, FAIR Plan and flood.","inLanguage":"en-US","isPartOf":{"@id":"https://pennsylvaniainsuranceappraiser.com/#website"},"about":{"@id":"https://pennsylvaniainsuranceappraiser.com/#business"},"publisher":{"@id":"https://pennsylvaniainsuranceappraiser.com/#business"},"dateModified":"2026-11-14","primaryImageOfPage":{"@type":"ImageObject","@id":"https://pennsylvaniainsuranceappraiser.com/insurance-appraisal-faq/#primaryimage","url":"https://pennsylvaniainsuranceappraiser.com/assets/img/photos/interior.webp","contentUrl":"https://pennsylvaniainsuranceappraiser.com/assets/img/photos/interior.webp","width":1200,"height":800},"breadcrumb":{"@id":"https://pennsylvaniainsuranceappraiser.com/insurance-appraisal-faq/#breadcrumb"},"mainEntity":{"@id":"https://pennsylvaniainsuranceappraiser.com/insurance-appraisal-faq/#faq"}},{"@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"https://pennsylvaniainsuranceappraiser.com/"},{"@type":"ListItem","position":2,"name":"Insurance appraisal FAQ","item":"https://pennsylvaniainsuranceappraiser.com/insurance-appraisal-faq/"}],"@id":"https://pennsylvaniainsuranceappraiser.com/insurance-appraisal-faq/#breadcrumb"},{"@type":"FAQPage","mainEntity":[{"@type":"Question","name":"What is insurance appraisal?","acceptedAnswer":{"@type":"Answer","text":"It’s a process in most property policies for settling disagreements about the amount of a covered loss. Each side names an appraiser, the appraisers pick an umpire, and an award signed by any two of the three sets the amount."}},{"@type":"Question","name":"When does appraisal make sense?","acceptedAnswer":{"@type":"Answer","text":"When the insurer accepts that the loss is covered but its estimate is well below what repairs actually cost. It is a poor fit when the claim has been denied outright or when the gap is small compared with the fees."}},{"@type":"Question","name":"Who can demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Either you or the insurance company, as long as the policy contains an appraisal provision. The demand should be in writing and should cite that provision."}},{"@type":"Question","name":"Is an insurance appraiser the same as a real estate appraiser?","acceptedAnswer":{"@type":"Answer","text":"No. A real estate appraiser estimates what a property would sell for. An insurance appraiser values the cost to repair or replace damaged property under the terms of the policy."}},{"@type":"Question","name":"What’s the difference between a public adjuster, an appraiser and an attorney?","acceptedAnswer":{"@type":"Answer","text":"A public adjuster is licensed by the Pennsylvania Insurance Department to prepare and negotiate your claim with the insurer. An appraiser serves on an appraisal panel to value a disputed loss, and an attorney gives legal advice and handles coverage, bad-faith and litigation issues."}},{"@type":"Question","name":"How much does an insurance appraiser cost?","acceptedAnswer":{"@type":"Answer","text":"Arrangements vary and can include flat fees, hourly rates or other structures. Each side pays its own appraiser and usually half of the umpire’s fee, so get the terms in writing before you sign."}},{"@type":"Question","name":"Who pays the umpire?","acceptedAnswer":{"@type":"Answer","text":"Most policies split the umpire’s fee equally between you and the insurer. Your policy’s appraisal clause will spell out the split."}},{"@type":"Question","name":"Is appraisal worth it for a small difference?","acceptedAnswer":{"@type":"Answer","text":"Often not. If the gap is only a few thousand dollars, fees can absorb most of any increase, so run the numbers with our claim gap fee projector before deciding."}},{"@type":"Question","name":"Can I get my appraisal costs back from the insurer?","acceptedAnswer":{"@type":"Answer","text":"Usually not through the appraisal itself, since the panel decides the amount of loss rather than fees or damages. Ask a Pennsylvania attorney whether any other route applies to your situation."}},{"@type":"Question","name":"How long does appraisal take?","acceptedAnswer":{"@type":"Answer","text":"Many residential appraisals wrap up within a couple of months once both appraisers are named. Large commercial losses, heavy contents claims or disputes that need an umpire can take longer."}},{"@type":"Question","name":"Does appraisal stop the one-year suit clause?","acceptedAnswer":{"@type":"Answer","text":"Not necessarily. Many Pennsylvania policies require a lawsuit within one year of the date of loss, courts have generally enforced that, and appraisal may not pause the clock unless the policy or a written agreement says so — talk to a Pennsylvania attorney early."}},{"@type":"Question","name":"How long do I have to name my appraiser?","acceptedAnswer":{"@type":"Answer","text":"Many policies allow 20 days from the written demand, but the number varies. Check your policy on the day you send or receive a demand."}},{"@type":"Question","name":"Is there a deadline to demand appraisal?","acceptedAnswer":{"@type":"Answer","text":"Some policies set one and many don’t, but waiting can still hurt you because the suit-limitation clause keeps running. Document the dispute and decide promptly."}},{"@type":"Question","name":"What happens if the appraisers can’t agree on an umpire?","acceptedAnswer":{"@type":"Answer","text":"Policies typically let either party ask a court of record in the county where the property sits to appoint one, which in Pennsylvania is generally the county court of common pleas. Your policy will say how and when."}},{"@type":"Question","name":"Who regulates insurance companies in Pennsylvania?","acceptedAnswer":{"@type":"Answer","text":"The Pennsylvania Insurance Department, led by the Insurance Commissioner. It accepts consumer complaints about insurers and licenses public adjusters."}},{"@type":"Question","name":"What is the Pennsylvania FAIR Plan?","acceptedAnswer":{"@type":"Answer","text":"It’s the state’s insurer of last resort for property owners who can’t find coverage in the regular market. FAIR Plan policies have their own terms, so read the appraisal and suit-limitation language carefully."}},{"@type":"Question","name":"Does Pennsylvania have a bad-faith law?","acceptedAnswer":{"@type":"Answer","text":"Yes. Pennsylvania’s bad-faith statute (42 Pa.C.S. § 8371) lets a court award interest, punitive damages, court costs and attorney fees if it finds an insurer acted in bad faith toward its insured, but appraisal does not decide bad faith."}},{"@type":"Question","name":"Does my homeowner policy cover flood or mine subsidence?","acceptedAnswer":{"@type":"Answer","text":"Standard homeowner policies exclude flood, which requires an NFIP or private flood policy, and usually exclude earth movement. The Mine Subsidence Insurance program run by the Pennsylvania Department of Environmental Protection offers separate coverage for damage from underground coal mine collapse."}},{"@type":"Question","name":"Are there rules about how fast insurers must handle claims?","acceptedAnswer":{"@type":"Answer","text":"Pennsylvania’s Unfair Insurance Practices Act and related claim-handling regulations set general standards for prompt, fair handling. If you believe an insurer is ignoring them, you can file a complaint with the Pennsylvania Insurance Department."}},{"@type":"Question","name":"Will demanding appraisal upset my insurer?","acceptedAnswer":{"@type":"Answer","text":"Appraisal is a normal part of the policy and insurers use it too. Keeping communication professional and well documented helps the process run smoothly."}},{"@type":"Question","name":"Can my roofer or contractor be my appraiser?","acceptedAnswer":{"@type":"Answer","text":"Usually not a good idea, because most policies require a disinterested appraiser and a contractor who will do the work has a stake in the result. Your contractor can still supply estimates, photos and testimony to your appraiser."}},{"@type":"Question","name":"Should I keep talking to the adjuster during appraisal?","acceptedAnswer":{"@type":"Answer","text":"Yes, stay responsive and keep everything in writing. Your appraiser handles the valuation discussions with the other appraiser, but the insurer may still need documents or access."}},{"@type":"Question","name":"Can I start repairs before the appraisal is finished?","acceptedAnswer":{"@type":"Answer","text":"You generally must take reasonable steps to prevent further damage, and that mitigation should be documented with photos and receipts. Before major permanent repairs, make sure both appraisers have seen or recorded the damage."}}],"@id":"https://pennsylvaniainsuranceappraiser.com/insurance-appraisal-faq/#faq"}]}</script>
</head>
